INSERT INTO `biz_incentive_record` VALUES (10,42,20,28,'2026上半年',NULL,NULL,34,NULL,NULL,NULL,NULL,NULL,NULL,5,1,'uploaded','2026-06-26 11:24:36','2026-06-26 11:24:36'),(11,42,40,28,'2026上半年',NULL,NULL,35,NULL,NULL,NULL,NULL,NULL,NULL,1,1,'uploaded','2026-06-26 11:27:09','2026-06-26 11:27:09'),(14,11,11,26,'2026上半年','化工','橡胶',NULL,NULL,40,41,NULL,NULL,NULL,10,0,'uploaded','2026-06-29 15:33:57','2026-06-29 15:33:57'),(18,57,40,305,'2026上半年','化工','涂层BSQ1',NULL,'酸碱卸药泵房腐蚀严重，酸性气体、碱性气体腐蚀。',47,46,45,NULL,NULL,3,0,'uploaded','2026-07-14 22:14:05','2026-07-14 22:14:05'),(19,55,41,460,'2026上半年','机械','防滑楼梯板',NULL,'叶片磨具人员走动频繁，多次发生摔倒事件',49,48,50,NULL,NULL,3,0,'uploaded','2026-07-28 21:24:39','2026-07-28 21:24:39'),(20,55,40,328,'2026上半年','有色金属','涂层BSQL',NULL,'反应釜搅拌棒腐蚀严重，在新的与旧的上刷涂BSQL',51,52,53,NULL,NULL,3,0,'uploaded','2026-07-28 21:35:29','2026-07-28 21:35:29'),(21,38,30,494,'2026上半年','煤矿','全固体聚合涂层SQ1',NULL,'风机设备外防腐：表面腐蚀严重，刷漆半年开始部分脱落，不满足煤矿大型设备标准化管理要求。',54,NULL,NULL,NULL,NULL,2,1,'uploaded','2026-07-29 18:43:00','2026-07-29 18:43:00'),(22,38,30,494,'2026上半年','煤矿','涂层SQ1',NULL,'风机设备里外均防腐：腐蚀严重，需要对设备里外进行防腐处理',55,NULL,NULL,NULL,NULL,2,0,'uploaded','2026-07-29 18:44:13','2026-07-29 18:44:13'),(25,38,40,335,'2026上半年','冶金','中阳钢铁二轧钢地下水管道外表面防腐试点',NULL,'原管道腐蚀严重，更换新管后刷BSQ1进行实验，效果好，可在二轧钢推广',63,62,64,NULL,NULL,3,1,'uploaded','2026-07-29 18:55:02','2026-07-29 18:55:02'),(26,38,40,335,'2026上半年','冶金','BSQ1',NULL,'二炼钢煤气管道弯头腐蚀冲刷严重，打磨除锈后，涂五层BSQ1，做实验，看是否满足现场工况！',66,65,67,NULL,NULL,3,1,'uploaded','2026-07-29 18:55:27','2026-07-29 18:55:27'),(27,51,32,276,'2026上半年','化工','SC胶心盘根',NULL,'我车间F2循环泵，两侧都有填料室，每侧都是采用的2+3，静压扬程是7.5米；介质为泥水混合液，里面包含液碱，甲醇，磷盐，氨氮，COD等；温度在35~40℃之间；内侧加装2道盘根，外侧加装3道盘根，共计十道盘根。\n原来使用的四氟或牛油的盘根，密封效果差，易漏料，使用周期短（不超过一星期），更换频繁，影响了生产的连续性，增加了现场环境管理的工作，',69,NULL,NULL,NULL,'使用艾志23SC盘根，替代原来使用的盘根。\n艾志23SC盘根采用耐磨芳纶纤维和PTFE丝纤维共同编织而成，有超强弹力补偿，有效结合了芳纶纤维的高强度与高耐磨性能PTFE的自润滑性能，耐磨损、柔韧性好。良好的自润滑性能减少了密封件对轴的磨损，同时增加了密封的抗腐蚀性能，尤其适用于灰渣泵、渣浆泵等磨损工况。',0,1,'uploaded','2026-07-29 20:21:34','2026-07-29 20:21:34'),(28,51,30,274,'2026上半年','化工','超级包涂层',NULL,'客户水处理部门，除盐水厂房腐蚀严重，介质有氯化钠，硫酸钠，芒硝，之前已经做过试点，做成方案',NULL,NULL,43,NULL,NULL,0,1,'uploaded','2026-07-29 20:22:22','2026-07-29 20:22:22'),(31,51,43,274,'2026上半年','化工','轴保器',NULL,'客户处的氧化风机，使用的传统骨架油封，转速快，温度高，骨架油封和O型密封圈的耐热，耐磨性差，加上安装时候的失误，导致经常泄露',71,73,70,NULL,NULL,1,1,'uploaded','2026-07-29 20:50:00','2026-07-29 20:50:00'),(37,1,11,560,'2026上半年','冶金','相关产品说明',NULL,'安装前问题',44,77,78,76,'安装备注',10,1,'uploaded','2026-07-30 13:08:06','2026-07-30 13:08:06'),(38,1,1,249,'2026上半年',NULL,NULL,NULL,'API测试-安装前问题',NULL,NULL,NULL,NULL,'API测试-安装备注',0,0,'uploaded','2026-07-30 15:49:38','2026-07-30 15:49:38');
